// Pull published products from cms.weeblab.net into landing/ and demo/ cms-catalog.js.
// Run: npm run cms:sync   (reads CMS_API_KEY, CMS_SITE_ID, CMS_CONTENT_TYPE_ID from .env.cms or the environment)
// The token stays on this machine: the site only ships the generated file, so no key in the browser and no CORS.
import { writeFileSync } from 'node:fs';
import assert from 'node:assert/strict';

const { CMS_API_KEY, CMS_SITE_ID, CMS_CONTENT_TYPE_ID } = process.env;
const CMS = process.env.CMS_URL || 'https://cms.weeblab.net/api';
// Seeded images point at GitHub Pages; turn them back into paths relative to the site folder.
const PAGES = 'https://grant-tung.github.io/web_keyboard/landing/';
if (!CMS_API_KEY || !CMS_SITE_ID || !CMS_CONTENT_TYPE_ID) {
  console.error('Missing CMS_API_KEY / CMS_SITE_ID / CMS_CONTENT_TYPE_ID (put them in .env.cms)');
  process.exit(1);
}

const url = `${CMS}/content?siteId=${CMS_SITE_ID}&contentTypeId=${CMS_CONTENT_TYPE_ID}&status=published`;
const res = await fetch(url, { headers: { 'x-api-key': CMS_API_KEY } });
if (!res.ok) throw new Error(`CMS ${res.status}: ${await res.text()}`);
const entries = await res.json();

const products = entries
  .map((e) => {
    const { extra, images, sortOrder, title, slug, ...fields } = e.data || {};
    const imgs = (images || []).map((m) => (m?.url || '').replace(PAGES, '')).filter(Boolean);
    return {
      ...extra,
      id: e.slug,
      name: e.title,
      ...fields,
      price: Number(fields.price) || 0,
      inStock: fields.inStock !== false,
      // products shown only through their colours have no top-level imgs; keep it absent, not []
      ...(imgs.length ? { imgs } : {}),
      _order: Number(sortOrder ?? 1e9),
    };
  })
  .sort((a, b) => a._order - b._order)
  .map(({ _order, ...p }) => p);

// Never overwrite the catalog with something broken: an empty file would silently fall back to the built-in list.
assert.ok(products.length > 0, 'CMS returned no published products — nothing written');
for (const p of products) assert.ok(p.id && p.name && p.category, `product missing id/name/category: ${JSON.stringify(p).slice(0, 120)}`);

const body = `// Generated by scripts/cms-sync.mjs from cms.weeblab.net — do not edit by hand. Empty = use the built-in catalog in app.js.\nexport default ${JSON.stringify(products, null, 2)};\n`;
for (const dir of ['landing', 'demo']) writeFileSync(new URL(`../${dir}/cms-catalog.js`, import.meta.url), body);
console.log(`Synced ${products.length} products from the CMS into landing/ and demo/ cms-catalog.js`);
